const reorderPlansByTenant = `-- name: ReorderPlansByTenant :execrows
WITH requested AS (
  SELECT plan_id, ordinal
  FROM unnest($2::uuid[]) WITH ORDINALITY AS item(plan_id, ordinal)
), eligible AS (
  SELECT requested.plan_id, requested.ordinal
  FROM requested
  JOIN ai_sub_plans p ON p.id = requested.plan_id AND p.tenant_id = $1
), valid AS (
  SELECT count(*) = cardinality($2::uuid[]) AS ok FROM eligible
)
UPDATE ai_sub_plans p
SET sort_order = eligible.ordinal::integer * 10,
    updated_at = now()
FROM eligible, valid
WHERE valid.ok AND p.id = eligible.plan_id
`

type ReorderPlansByTenantParams struct {
	TenantID string        `json:"tenant_id"`
	Column2  []pgtype.UUID `json:"column_2"`
}

func (q *Queries) ReorderPlansByTenant(ctx context.Context, arg ReorderPlansByTenantParams) (int64, error) {
	result, err := q.db.Exec(ctx, reorderPlansByTenant, arg.TenantID, arg.Column2)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

