const updatePlanPurchasePolicy = `-- name: UpdatePlanPurchasePolicy :one
UPDATE ai_sub_plan_purchase_policies SET
  lifetime_max_purchases=$2,
  period_type=$3,
  period_max_purchases=$4,
  rolling_window_hours=$5,
  calendar_unit=$6,
  calendar_timezone=$7,
  allow_advance_purchase=$8,
  version=version+1,
  updated_at=now()
WHERE plan_id=$1
  AND ROW(
    lifetime_max_purchases, period_type, period_max_purchases,
    rolling_window_hours, calendar_unit, calendar_timezone,
    allow_advance_purchase
  ) IS DISTINCT FROM ROW($2,$3,$4,$5,$6,$7,$8)
RETURNING plan_id, lifetime_max_purchases, period_type, period_max_purchases, rolling_window_hours, calendar_unit, calendar_timezone, allow_advance_purchase, version, created_at, updated_at
`

type UpdatePlanPurchasePolicyParams struct {
	PlanID               pgtype.UUID `json:"plan_id"`
	LifetimeMaxPurchases pgtype.Int4 `json:"lifetime_max_purchases"`
	PeriodType           string      `json:"period_type"`
	PeriodMaxPurchases   pgtype.Int4 `json:"period_max_purchases"`
	RollingWindowHours   pgtype.Int4 `json:"rolling_window_hours"`
	CalendarUnit         pgtype.Text `json:"calendar_unit"`
	CalendarTimezone     pgtype.Text `json:"calendar_timezone"`
	AllowAdvancePurchase bool        `json:"allow_advance_purchase"`
}

// Only policy changes increment the version; unrelated plan edits do not.
func (q *Queries) UpdatePlanPurchasePolicy(ctx context.Context, arg UpdatePlanPurchasePolicyParams) (AiSubPlanPurchasePolicy, error) {
	row := q.db.QueryRow(ctx, updatePlanPurchasePolicy,
		arg.PlanID,
		arg.LifetimeMaxPurchases,
		arg.PeriodType,
		arg.PeriodMaxPurchases,
		arg.RollingWindowHours,
		arg.CalendarUnit,
		arg.CalendarTimezone,
		arg.AllowAdvancePurchase,
	)
	var i AiSubPlanPurchasePolicy
	err := row.Scan(
		&i.PlanID,
		&i.LifetimeMaxPurchases,
		&i.PeriodType,
		&i.PeriodMaxPurchases,
		&i.RollingWindowHours,
		&i.CalendarUnit,
		&i.CalendarTimezone,
		&i.AllowAdvancePurchase,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const validateGroupsForTenant = `-- name: ValidateGroupsForTenant :many
SELECT g.id::text
FROM ai_groups g
WHERE g.id = ANY($2::uuid[])
  AND g.status = 'active'
  AND g.tenant_id = $1
`

type ValidateGroupsForTenantParams struct {
	TenantID string        `json:"tenant_id"`
	Column2  []pgtype.UUID `json:"column_2"`
}

// 校验入参分组中「active 且归属该租户」的子集。
// 返回集与入参集比对，缺失即非法分组。
func (q *Queries) ValidateGroupsForTenant(ctx context.Context, arg ValidateGroupsForTenantParams) ([]string, error) {
	rows, err := q.db.Query(ctx, validateGroupsForTenant, arg.TenantID, arg.Column2)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var g_id string
		if err := rows.Scan(&g_id); err != nil {
			return nil, err
		}
		items = append(items, g_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
